import workcell

def collides(x, y, z=15.0):
    r = workcell.robot("move", f"{x:.3f}", f"{y:.3f}", f"{z:.1f}")
    return (not r.ok), r.text

def find_edge(vary, fixed, free, occ, axis, iters=10, z=15.0):
    lo, hi = free, occ  # lo known free, hi known collide
    for i in range(iters):
        mid = (lo+hi)/2
        if axis=='x':
            c, msg = collides(mid, fixed, z)
        else:
            c, msg = collides(fixed, mid, z)
        if c:
            hi = mid
        else:
            lo = mid
    # return free side and collide side
    edge = (lo+hi)/2
    print(f"edge {axis} fixed={fixed:.2f}: free={lo:.3f} collide={hi:.3f} mid={edge:.3f}")
    return edge

# Ensure we start from a known free pose so moves don't fail for other reasons
print("reset", workcell.robot("move","500","400","40").text)

# North: large y free, smaller y collide. x samples
print("=== NORTH (max y) ===")
for x in (390, 425, 460):
    # find a free y first
    find_edge('y', x, free=360, occ=250, axis='y')

print("=== SOUTH (min y) ===")
for x in (390, 425, 460):
    find_edge('y', x, free=140, occ=250, axis='y')

